-- Principle 2: תפקיד המורה כמוביל למידה אנושית
with p as (
  insert into public.principles (
    scope, municipality_id, order_index, short_label, title, icon, color_name, accent_color,
    bg_light, text_dark, short_summary, rationale, gaps_solved, added_value,
    implementation_strategy, sacrifices_required, ecosystem_partnerships, kpis,
    teacher_deliverable, student_deliverable, first_step, is_active
  ) values (
    'municipal', '00000000-0000-4000-8000-000000000001', 2, 'למידה אנושית', 'תפקיד המורה כמוביל למידה אנושית', 'fa-solid fa-heart-pulse', 'rose', '#f43f5e',
    'bg-rose-50', 'text-rose-900', 'הבראת המרכיב הרגשי-חברתי בשיח הבית-ספרי ומעבר של מורים לתפקיד מנטורינג.', 'בעידן שבו הידע זמין והבינה המלאכותית מייעלת את התהליכים הטכניים, תפקיד המורה עובר את השינוי הדרמטי ביותר: מעמדה של ''מעביר מידע פרונטלי'' לעמדה של ''מוביל למידה אנושית''. המורה הופך למנטור, למנחה, למפתח חוסן, חשיבה ביקורתית, אמפתיה ואחריות ערכית. קשר בין-אישי קרוב וחם הוא הבסיס שעליו נשענת הלמידה כולה.', ARRAY['ניכור וחוסר שייכות: פותר את תחושת ה''רואי ואינו נראה'' של תלמידים במערכות גדולות, ומחזק את המוגנות הרגשית.', 'פסיביות בלמידה: מונע למידה שטחית המבוססת על הכתבה, ומעביר את הכיתה לשיח דיאלוגי, דיונים ערכיים והטלת ספק מונחית.'], 'יצירת עמוד שדרה ערכי ומוסרי אצל הלומד, המאפשר לו לנווט בעולם דיגיטלי רועש ומורכב מתוך מוגנות פנימית ואחריות חברתית.',
    ARRAY['שיבוץ חלונות זמן מוגנים וקבועים במערכת השעות לטובת שיחות אישיות (מורה-תלמיד) וקבוצות שיח מונחות (SEL - למידה רגשית חברתית).', 'הקמת קהילות למידה מקצועיות (קל"מ) לצוות המורים לעיבוד התפקיד החדש ולימוד פרקטיקות מנטורינג.'], 'צמצום משמעותי של זמן ההרצאה הפרונטלית של המורה מול כלל הכיתה (לא יותר מ-15 דקות בפתיחת שיעור). הפחתת העיסוק הבלעדי בציונים יבשים ומעבר למשוב מעצים ודיאלוגי.', 'שיתוף פעולה הדוק עם השירות הפסיכולוגי החינוכי (שפ"ח) להכשרת המורים כמפתחי חוסן, וחיבור לתנועות נוער וארגוני חברה אזרחית בעיר להובלת יוזמות ערכיות.', ARRAY['אחוז התלמידים המדווחים בשאלונים על קיומו של ''מבוגר משמעותי אחד לפחות'' שרואה ומקשיב להם בבית הספר.', 'היקף שעות המנטורינג והשיח הרגשי-חברתי המבוצעות בפועל ומדווחות במערכת הניהול הבית-ספרית.'],
    'מורה שמתפקד כמנטור ומנחה קבוצות, המנהל קשר אישי רציף ומעצים עם קבוצת תלמידים מוגדרת.', 'תלמיד בעל מודעות עצמית גבוהה, המפגין אמפתיה, מעורבות חברתית ויכולת לנהל קונפליקטים בצורה מכבדת.', 'פתיחת שנת הלימודים ברצף של שיחות אישיות מובנות (''מרתון הקשבה'') של מחנכים ומורים עם כל תלמיד ותלמידה, במקום פתיחה ישירה במבחני אבחון לימודיים יבשים.', true
  ) returning id
),
s as (
  insert into public.principle_sources (principle_id, title, description, url, keywords, order_index)
  select p.id, x.title, x.description, x.url, x.keywords, x.ord from p,
  (values
    ('אגף שפ"י - משרד החינוך', 'התוכנית הלאומית להטמעת SEL (Social-Emotional Learning) במערכת החינוך המציגה מערכים, מחקרים ותפיסות להפיכת המורה למפתח חוסן וקשר בין-אישי.', 'https://shapi.education.gov.il', 'למידה רגשית חברתית SEL / המורה כמנטור', 0),
    ('מכון אבני ראשה וג''וינט אשלים', 'ניירות עמדה ומודלים אופרטיביים בנושא קהילות למידה מקצועיות (קל"מ) ומנטורינג אישי שבועי של מורים לתלמידיהם.', 'https://www.avneyrosha.org.il', 'המורה כמנטור ומוביל דיאלוג', 1)
  ) as x(title, description, url, keywords, ord)
  returning 1
),
r as (
  insert into public.principle_rubric_levels (principle_id, level, name, description)
  select p.id, x.level, x.name, x.description from p,
  (values
    (1, 'ראשוני / ניצוצות', 'המורה נתפס ומתפקד כ''צינור להעברת מידע'' בלבד (הוראה פרונטלית דומיננטית). השיח המרכזי בין מורים לתלמידים סובב סביב ציונים, הישגים יבשים ובעיות משמעת.'),
    (2, 'מתפתח / איים של חדשנות', 'מורים מנסים לשלב שגרות של למידה רגשית-חברתית (SEL) ושיח רגשי, אך הדבר נעשה באופן אקראי (למשל, רק בשיעורי חינוך או בימי שישי) ואין לכך גיבוי או פינוי זמן מובנה במערכת השעות הכללית.'),
    (3, 'מוטמע / שגרה מוסדית', 'מוגדרים חלונות זמן קבועים, מוגנים ובלתי-ניתנים לביטול במערכת השעות לטובת שיחות אישיות (מנטורינג) וקבוצות שיח מונחות (SEL). זמן ההרצאה הפרונטלית של המורה מוגבל ניהולית לעד 15 דקות בפתיחת השיעור, והשאר מוקדש לדיאלוג והנחיה. פועלת קהילת למידה מקצועית (קל"מ) מוסדית לעיבוד התפקיד האנושי.'),
    (4, 'חלוצי / חזון עירוני מלא', 'המורה מתפקד כמנטור ומנחה מובהק המפתח חוסן, חשיבה ביקורתית ומצפן ערכי אצל הלומד. הקשר הבין-אישי הקרוב והחם הוא המנוע והתשתית לכל הלמידה הבית-ספרית. 100% מהתלמידים מדווחים בשאלונים על קיומו של ''מבוגר משמעותי'' שרואה ומקשיב להם באמת.')
  ) as x(level, name, description)
  returning 1
),
b as (
  insert into public.activity_bank_items (
    scope, municipality_id, principle_id, slug, title, category, source,
    short, goal, audience, contact, description, is_active
  )
  select 'municipal', '00000000-0000-4000-8000-000000000001', p.id, x.slug, x.title, x.category, x.source::public.task_source,
         x.short, x.goal, x.audience, x.contact, x.description, true
  from p, (values
    ('p2-1', 'שעות מנטורינג אישי קבועות', 'בית-ספרי', 'עירוני', 'חלונות זמן מוגנים לשיחות אישיות עם תלמידים.', 'מעבר המורה מ"מעביר מידע" ל"מנטור" — קיבוע זמן מוגן במערכת לשיחות אישיות וליווי.', 'מחנכים וצוות בית הספר.', 'סגנ/ית המנהל/ת ורכז/ת חברתי.', 'שיבוץ קבוע ובלתי-ניתן-לביטול במערכת השעות לשיחות מנטורינג אישיות וקבוצות שיח מונחות.'),
    ('p2-2', 'קל"מ – קהילת למידה רגשית-חברתית', 'קהילה', 'עירוני', 'קהילת מורים לעיבוד התפקיד האנושי והרגשי.', 'פיתוח שיח רגשי-חברתי (SEL) בצוות והבראת המרכיב האנושי בעשייה הבית-ספרית.', 'כלל צוות החינוך.', 'היועצת החינוכית והשירות הפסיכולוגי (שפ"ח).', 'מפגשי קהילה קבועים לעיבוד דילמות מהשטח, פיתוח כלים לשיח רגשי וחיזוק החוסן של המורים והתלמידים.'),
    ('p2-3', 'סדנת תקשורת מקרבת ושיח מיטיב', 'סדנה', 'עירוני', 'הקניית כלים לדיאלוג חם ומקרב עם תלמידים.', 'שדרוג יכולות התקשורת של הצוות לבניית קשר בין-אישי קרוב כבסיס ללמידה.', 'מורים ומחנכים.', 'היועצת החינוכית / מנחה חיצוני.', 'סדנה מעשית בתקשורת מקרבת (NVC) והקשבה פעילה, עם תרגול תרחישים מהשטח הבית-ספרי.'),
    ('p2-4', 'מדד "מבוגר משמעותי"', 'דיגיטלי', 'עירוני', 'שאלון אנונימי למיפוי תחושת השייכות של התלמידים.', 'מדידת קיומו של "מבוגר משמעותי" לכל תלמיד והנעת פעולה ממוקדת לצמצום ניכור.', 'כלל תלמידי בית הספר.', 'רכז/ת התקשוב והיועצת.', 'העברת שאלון דיגיטלי תקופתי, ניתוח התוצאות וזיהוי תלמידים הזקוקים לחיזוק הקשר האישי.'),
    ('p2-5', 'הכשרת מורים-חונכים עירונית', 'עירוני', 'עירוני', 'תוכנית עירונית להכשרת מנטורים בבית הספר.', 'בניית מערך חונכות מקצועי ומובנה בבית הספר בליווי עירוני.', 'מורים מובילים ורכזי שכבות.', 'אגף החינוך — פיתוח מקצועי.', 'מסלול הכשרה עירוני המקנה כלים לחונכות אישית, עם ליווי ומפגשי עמיתים לאורך השנה.')
  ) as x(slug, title, category, source, short, goal, audience, contact, description)
  returning 1
)
select (select count(*) from s) as sources, (select count(*) from r) as rubric, (select count(*) from b) as bank;

-- Principle 3: הטמעת AI כתשתית
with p as (
  insert into public.principles (
    scope, municipality_id, order_index, short_label, title, icon, color_name, accent_color,
    bg_light, text_dark, short_summary, rationale, gaps_solved, added_value,
    implementation_strategy, sacrifices_required, ecosystem_partnerships, kpis,
    teacher_deliverable, student_deliverable, first_step, is_active
  ) values (
    'municipal', '00000000-0000-4000-8000-000000000001', 3, 'תשתית AI', 'הטמעת AI כתשתית', 'fa-solid fa-brain', 'purple', '#a855f7',
    'bg-purple-50', 'text-purple-900', 'הפיכת ה-AI לתשתית ניהולית ופדגוגית מובילה שמפנה זמן למפגש אנושי.', 'הבינה המלאכותית (AI) אינה כלי טכנולוגי חולף או יישום להעשרה בלבד; היא מהווה תשתית ארגונית ופדגוגית משנת פרדיגמה. כדי לחולל שינוי עמוק, ההטמעה חייבת להתחיל משדרת המנהיגות – מנהלים ומורים – שחווים את הכלי כחלק משגרת עבודתם. השימוש וההתנסות בבינה מלאכותית הם תנאי הכרחי שאינו בגדר רשות, והוא חייב להתחיל בראש ובראשונה בדרג המנהלים והמורים. החזון המרכזי העומד בבסיס עיקרון זה הוא ששימוש מושכל, יעיל ומקצועי בבינה מלאכותית יאפשר לצוותי החינוך להתפנות ממשימות רובוטיות או טכניות, ובכך לדייק את המענים הפדגוגיים ולאפשר מפגש אנושי, חם ופרטני עם התלמידים. בנוסף, שימוש ביכולות מתקדמות בבינה מלאכותית יוכלו לקדם למידה פרסונלית יעילה לתלמידים ופיתוח מקצועי אישי ודיפרנציאלי לצוותי ההוראה.', ARRAY['שחיקה ועומס בירוקרטי: ה-AI פותר את הפער הכרוני של מחסור בזמן במערכת החינוך, על ידי אוטומציה של משימות אדמיניסטרטיביות וניהוליות.', 'קושי בפרסונליזציה: הכלי מאפשר למורה הבודד לפרוץ את מגבלת ''ההוראה לממוצע'' ולייצר מענים מבודלים לעשרות תלמידים במקביל.'], 'ככל שהבינה המלאכותית לוקחת על עצמה משימות טכניות ורובוטיות (כמו ניסוח, ניתוח נתונים ראשוני ובניית תבניות), כך מתפנה המשאב היקר מכול – זמן למפגש אנושי, רגשי ופרטני עם התלמיד.',
    ARRAY['סדירויות במערכת השעות: הגדרת ''עוגן למידה והתנסות'' קבוע לצוות המורים (למשל, 20 דקות ייעודיות בכל ישיבת מליאה או קהילת למידה מקצועית לחשיפה והתנסות בכלי AI חדשים). מינוי ''מוביל בינה מלאכותית'' בית-ספרי.', 'המנהל וצוות ההנהלה משלבים כלי AI בשגרות העבודה הניהוליות – החל מניתוח נתונים בית-ספריים מורכבים ויצירת תובנות פדגוגיות, ועד לניסוח פניות ממוקדות לקהילת ההורים וסיכום ישיבות פדגוגיות.', 'המורים נעזרים בבינה מלאכותית כ''עוזר הוראה אישי'' לתכנון מערכי שיעור מבודלים, לבניית משימות הערכה מגוונות ולפיתוח חומרי למידה המותאמים לרמות השונות בכיתה.', 'הזמן שנחסך למורים הודות לאוטומציה הניהולית והפדגוגית מתורגם באופן מובנה במערכת השעות לטובת שיחות אישיות, ליווי רגשי והנחיה פרטנית של לומדים.'], 'מעבר מכתיבה ידנית וממושכת של סילבוסים, מערכי שיעור ומבחנים מסורתיים, לעבודה מבוססת פרומפטים ובקרת איכות אנושית על תוצרי ה-AI.', 'חיבור הדוק למחלקת התקשוב העירונית לקבלת הרשאות, הגדרת מדיניות הגנת פרטיות ואבטחת מידע, ושיתוף פעולה עם הנהגת ההורים ליצירת מוגנות דיגיטלית.', ARRAY['אחוז המורים המדווחים על שימוש שבועי קבוע בכלי AI לתכנון פדגוגי.', 'קיומו של מאגר דיגיטלי בית-ספרי משותף של מערכי שיעור ומשימות הערכה שפותחו בשילוב AI.', 'עלייה במספר השעות האפקטיביות המוקדשות לשיחות אישיות עם תלמידים (כתוצאה מחסכון בזמן הניהולי).'],
    'כל מורה מחזיק ב-3 יחידות לימוד מבודלות (לרמות שונות) שפותחו, שופרו ובוקרו באמצעות AI, כולל משימות הערכה מותאמות.', 'התלמיד יודע להשתמש בבוט פנימי או בכלי AI מבוקר כסביבת עבודה לחקר, תוך הפעלת חשיבה ביקורתית על התוצרים.', 'מנהל בית הספר משתמש ב-AI לניתוח נתוני המשוב הבית-ספרי ולניסוח איגרת הפתיחה להורים. בישיבת המורים הראשונה מועברת סדנת בזק חווייתית (''קו-פיילוט לכל מורה'') להפגת חרדות ויצירת מוטיבציה.', true
  ) returning id
),
s as (
  insert into public.principle_sources (principle_id, title, description, url, keywords, order_index)
  select p.id, x.title, x.description, x.url, x.keywords, x.ord from p,
  (values
    ('הפורטל הפדגוגי - משרד החינוך', 'מדור בינה מלאכותית בפורטל הפדגוגי. כולל את המחוון הרשמי לשילוב בינה מלאכותית יוצרת (Generative AI) בהוראה ובלמידה, הנחיות אתיות ומדריכים למורים.', 'https://pop.education.gov.il', 'בינה מלאכותית בחינוך / פדגוגיה דיגיטלית AI', 0),
    ('איגוד האינטרנט הישראלי (ISOC-IL)', 'ניירות עמדה מפורטים, ימי עיון מוקלטים ומדריכים יישומיים שנכתבו על ידי מומחי טכנולוגיה וחינוך בנושא חשיבה ביקורתית ומגמות AI.', 'https://www.isoc.org.il', 'בינה מלאכותית במערכת החינוך', 1),
    ('מכון מופ"ת - מאמרים ואקדמיה', 'אסופת מאמרים אקדמיים בנושא השפעת ה-AI על תפקיד המורה, מודלים של Co-Pilot בהוראה ושינוי שיטות הערכה בעידן של בינה יוצרת.', 'https://www.mofet.macam.ac.il', 'בינה מלאכותית בביטאון דפים / קשר עין', 2)
  ) as x(title, description, url, keywords, ord)
  returning 1
),
r as (
  insert into public.principle_rubric_levels (principle_id, level, name, description)
  select p.id, x.level, x.name, x.description from p,
  (values
    (1, 'ראשוני / ניצוצות', 'מורים בודדים ''משוגעים לדבר'' משתמשים בכלי AI באופן עצמאי. אין מדיניות או שגרת עבודה ניהולית, וקיימת רמת רתיעה או חרדה מסוימת בקרב חלקים מהצוות.'),
    (2, 'מתפתח / איים של חדשנות', 'הנהלת בית הספר עושה שימוש ראשוני בכלי AI לצרכים ניהולית. בוצעה השתלמות חשיפה מוסדית לצוות המורים, אך השימוש הפדגוגי עדיין אקראי ולא מחייב.'),
    (3, 'מוטמע / שגרה מוסדית', 'ה-AI משולב באופן קבוע בשגרות הניהול וכתיבת התוכן של ההנהלה. מוגדר עוגן קבוע במערכת (במליאות או בקל"מ) להתנסות ב-AI. מורים משתמשים בכלי באופן קבוע לבניית מערכי שיעור ומשימות הערכה.'),
    (4, 'חלוצי / חזון עירוני מלא', 'ה-AI מהווה תשתית עמוקה ואינטגרלית לכלל התהליכים בארגון. הוכח מחקרית וארגונית כי שימוש מקצועי ומושכל ב-AI פינה למורים זמן אפקטיבי המוקדש כיום לשיחות אישיות ולמפגש אנושי פרטני עם התלמידים. התלמידים משתמשים ב-AI כסביבת עבודה מבוקרת לחקר עצמאי.')
  ) as x(level, name, description)
  returning 1
),
b as (
  insert into public.activity_bank_items (
    scope, municipality_id, principle_id, slug, title, category, source,
    short, goal, audience, contact, description, is_active
  )
  select 'municipal', '00000000-0000-4000-8000-000000000001', p.id, x.slug, x.title, x.category, x.source::public.task_source,
         x.short, x.goal, x.audience, x.contact, x.description, true
  from p, (values
    ('p3-1', 'השתלמות AI מוסדית לצוות', 'סדנה', 'עירוני', 'חשיפה והכשרה ראשונית של הצוות לכלי AI.', 'הפיכת השימוש ב-AI לשגרת עבודה ניהולית ופדגוגית, החל מדרג המנהיגות.', 'כלל צוות ההוראה וההנהלה.', 'רכז/ת התקשוב והפיקוח הפדגוגי.', 'השתלמות מוסדית מעשית ליצירת תוכן, תכנון שיעורים וייעול משימות ניהוליות באמצעות כלי בינה מלאכותית.'),
    ('p3-2', 'מדריך כלי AI בית-ספרי', 'דיגיטלי', 'עירוני', 'מאגר פנימי של כלים מומלצים ושימושים.', 'יצירת תשתית ידע אחידה לשימוש מושכל ואחראי ב-AI בכל הצוות.', 'מורים ורכזים.', 'רכז/ת התקשוב הבית-ספרי.', 'בניית מדריך דיגיטלי חי המרכז 3–5 כלי AI מועדפים, דוגמאות שימוש פדגוגיות והנחיות אתיות.'),
    ('p3-3', 'אמנת שימוש אחראי ואתי ב-AI', 'בית-ספרי', 'עירוני', 'גיבוש נוהל בית-ספרי לשימוש מושכל ב-AI.', 'עיגון שימוש אחראי, שקוף ואתי ב-AI כחלק מתרבות בית הספר.', 'הנהלה, מורים, תלמידים והורים.', 'הנהלת בית הספר ומפקח/ת המוסד.', 'תהליך משותף לכתיבת אמנה המגדירה כללי שימוש, יושרה אקדמית ופרטיות, ואימוצה על ידי הקהילה.'),
    ('p3-4', 'מרכז חדשנות עירוני – AI', 'עירוני', 'עירוני', 'ליווי והתנסות במרכז ה-AI העירוני.', 'מינוף משאבי הרשות להתנסות מעשית ומעמיקה בבינה מלאכותית.', 'מורים מובילים ונבחרות תלמידים.', 'אגף טכנולוגיות וחדשנות, מינהל החינוך.', 'מסלול התנסות במרכז העירוני הכולל סדנאות, ליווי מנטור ופיתוח מיזם AI בית-ספרי.'),
    ('p3-5', 'נבחרת תלמידים מפתחי AI', 'קהילה', 'עירוני', 'חונכות תלמידים לפיתוח פתרונות מבוססי AI.', 'טיפוח מצוינות ויזמות תלמידים סביב פיתוח כלים מבוססי בינה מלאכותית.', 'תלמידי חטיבה ותיכון.', 'רכז/ת מדעי המחשב והתקשוב.', 'הקמת נבחרת תלמידים המפתחת פתרונות AI קהילתיים ומציגה אותם ביריד החדשנות הבית-ספרי.')
  ) as x(slug, title, category, source, short, goal, audience, contact, description)
  returning 1
)
select (select count(*) from s) as sources, (select count(*) from r) as rubric, (select count(*) from b) as bank;

-- Principle 4: הטמעת מודל BYOD
with p as (
  insert into public.principles (
    scope, municipality_id, order_index, short_label, title, icon, color_name, accent_color,
    bg_light, text_dark, short_summary, rationale, gaps_solved, added_value,
    implementation_strategy, sacrifices_required, ecosystem_partnerships, kpis,
    teacher_deliverable, student_deliverable, first_step, is_active
  ) values (
    'municipal', '00000000-0000-4000-8000-000000000001', 4, 'מודל BYOD', 'הטמעת מודל BYOD', 'fa-solid fa-mobile-screen-button', 'cyan', '#06b6d4',
    'bg-cyan-50', 'text-cyan-900', 'רתום המכשירים האישיים בשילוב עבודה שיתופית וניהול מבוסס נתונים.', 'מודל ה-BYOD אינו הסדר לוגיסטי אלא תשתית פדגוגית חיונית המאפשרת למידה בכל מקום ובכל זמן. המטרה היא להפוך את המכשיר האישי של התלמיד (סמארטפון/טאבלט/לפטופ) מגורם מוסחות ומקור לבעיות משמעת, לכלי עבודה מרכזי, מעצים ומנוהל היטב בשירות הלמידה. למודל השפעה רחבה ועמוקה על המעשה החינוכי כולו. העיסוק המערכתי במודל זה אינו טכני בלבד ואינו מיועד לצורך הצטיידות חומרית גרידא או לשם הנצחת דרכי הלמידה וההוראה הקיימות באמצעות מסכים דיגיטליים. המטרה היא לשנות את הפרדיגמה של השימוש במכשיר הקצה האישי, ולהפוך אותו ממוקד של מוסחות לכלי עבודה פדגוגי מעצים. המודל יכול לפעול ולעבוד בכל רמה - משלב היסודי ועד לבוגר י״ב בתיכון. מודל זה מאפשר למורה להיות דינמי יותר, מאפשר תהליכי הוראה, למידה והערכה מעמיקים ודיפרנציאליים ויש בו הפוטנציאל לקידום חינוכי משמעותי.', ARRAY['רלוונטיות: מגשר על הפער שבין השימוש הדיגיטלי האינטנסיבי של התלמיד מחוץ לבית הספר לבין שיטות הלמידה המיושנות בתוכו. מאפשר פריצות דרך פדגוגיות וחוויית למידה שונה (כשנעשה נכון).', 'למידה שיתופית, פרויקטלית, יצירתית ודיפרנציאלית.', 'ניהול מבוסס נתונים: מעבר למהלך הזה מאפשר למורה וגם למנהל להוביל למידה וניהול מבוסס נתונים.', 'אוריינות דיגיטלית: מפתח אצל הבוגר אוריינות דיגיטלית משמעותית והיכרות ''טבעית'' עם דרישות מורכבות טכנולוגיות.', 'פער דיגיטלי וזמינות: פותר את המחסור הכרוני במחשבים זמינים בכיתות ומבטל את הצורך ב''נדודים'' לחדר מחשבים.'], 'חינוך לדיגיטליות אחראית תוך הדגשה שהמכשיר מיועד ליצירה, חקר ושיתופיות, ולא רק לצריכת תוכן פסיבית.',
    ARRAY['קביעת זמני הדרכה (ע״י מדריכה עירונית מנוסה) לצוות המוביל הבית ספרי - לחשיבה על הטמעה, אופן הביצוע, מדדי ההצלחה וביטויים ראשוניים להתחלה.', 'בניית תהליך הדרכתי לצוות השכבתי כולל השתתפות במליאות מורים ייעודיות לנושא.', 'מעבר מיידי לסביבת ענן מוסדרת - google classroom שם ירוכזו כל חומרי ההוראה למורה ולתלמיד. סביבה זו היא הבסיס (לצד מעבר לספרים דיגיטליים). זו התחלה משמעותית לקראת התקדמות פדגוגית.', 'עבודה במודל פרויקטלי - בסיס פדגוגי משמעותי להובלת מהלך ה BYOD.'], 'הפסקת עבודה עם דפי עבודה פיזיים מודפסים, ויתור על הכתבות כליות בכיתה והפחתת שימוש בספרים מודפסים לטובת מעבר מבוקר לספרים ומקורות מידע דיגיטליים.', 'למידה משמעותית מבתי ספר עירוניים הנמצאים כבר כמה שנים במהלך, ושיתוף פלטפורמות עם מחלקת המחשוב העירונית לסל קליטה ללומד.', ARRAY['הרגשת הבטחון של מורים בכלים הטכנולוגיים שנבחרו (יש לבחור מעט כאלה ולהעמיק בהם).', 'אחוז השיעורים שבהם נעשה שימוש במכשיר הקצה לצורך פדגוגי אקטיבי (חקר, שיתוף, יצירה).'],
    'מורה שמנהל כיתה דיגיטלית בביטחון, תוך שימוש בפלטפורמות עבודה שיתופיות ובדיקת הבנה בזמן אמת.', 'תלמיד שמגלה אחריות אישית, שולט בסביבת הלמידה הדיגיטלית שלו ומפגין התמצאות בסביבת הענן שלו (המרחב האישי בגוגל קלאסרום).', 'פתיחת השנה בתהליך מובנה של המדריכה המובילה עם צוות ההובלה הבית ספרי ופגישות קבועות עם הצוות השכבתי.', true
  ) returning id
),
s as (
  insert into public.principle_sources (principle_id, title, description, url, keywords, order_index)
  select p.id, x.title, x.description, x.url, x.keywords, x.ord from p,
  (values
    ('אתר משרד החינוך - חוזרי מנכ"ל', 'מסמכי המדיניות הרשמיים בנושא שילוב מכשירי קצה אישיים בבתי הספר, הכוללים הנחיות ארגוניות, פתרונות תקשוב, חוקי מוגנות ושמירה על שוויון הזדמנויות חברתי.', 'https://www.gov.il/he/departments/ministry_of_education', 'שילוב מכשירי קצה אישיים / אמנת BYOD', 0),
    ('איגוד האינטרנט הישראלי', 'ערכות מוכנות לבתי ספר לניסוח אמנות דיגיטליות משותפות (מורים-הורים-תלמידים), ומאמרים על הפיכת הסמארטפון מגורם מוסחות לכלי מחקר אקטיבי.', 'https://www.isoc.org.il', 'מוגנות ברשת -> אזרחות דיגיטלית בבתי ספר', 1)
  ) as x(title, description, url, keywords, ord)
  returning 1
),
r as (
  insert into public.principle_rubric_levels (principle_id, level, name, description)
  select p.id, x.level, x.name, x.description from p,
  (values
    (1, 'ראשוני / ניצוצות', 'המכשירים האישיים של התלמידים נתפסים כאויב או כמטרד מרכזי בכיתה המייצר בעיות משמעת ומוסחות. המדיניות היא הגנתית (''החרמה'' או ''בתיקים בלבד'') ללא כל שימוש פדגוגי.'),
    (2, 'מתפתח / איים של חדשנות', 'מורים בודדים מאפשרים לתלמידים להוציא מכשירים לטובת משימה נקודתית (כמו מענה על חידון Kahoot בסוף שיעור). אין אמנה בית-ספרית מוסדרת, ותשתית ה-WIFI אינה יציבה או מוגנת.'),
    (3, 'מוטמע / שגרה מוסדית', 'קיימת ''אמנת BYOD'' בית-ספרית פעילה שנכתבה בשותפות עם ההורים והתלמידים. בכיתות מיושמים ''חוקי רמזור'' מוסכמים לניהול המכשירים. השימוש במכשיר הוא חלק מובנה מהשיעור לצורך עבודה שיתופית, חקר וסקרים בזמן אמת. התשתית הבית-ספרית תומכת וערוכה לכך.'),
    (4, 'חלוצי / חזון עירוני מלא', 'המכשיר האישי הוא פלטפורמת למידה טבעית ואישית (Anywhere, Anytime Learning). התלמידים מנהלים את עצמם באחריות ובאופן אתי (אזרחות דיגיטלית). אירועי המשמעת סביב המכשירים אפסיים. קיים מנגנון השאלה עירוני מובנה המונע לחלוטין פערים חברתיים או חומריים בכיתה.')
  ) as x(level, name, description)
  returning 1
),
b as (
  insert into public.activity_bank_items (
    scope, municipality_id, principle_id, slug, title, category, source,
    short, goal, audience, contact, description, is_active
  )
  select 'municipal', '00000000-0000-4000-8000-000000000001', p.id, x.slug, x.title, x.category, x.source::public.task_source,
         x.short, x.goal, x.audience, x.contact, x.description, true
  from p, (values
    ('rother', 'בית רותר - חדשנות פדגוגית', 'בית רותר', 'עירוני', 'ביקור חווייתי וסדנת פיתוח מעשית בבית רותר.', 'התנסות מעשית, למידה חווייתית ופיתוח פרויקטים פדגוגיים ייחודיים המבוססים על מעבדת החדשנות של הרשות בבית רותר.', 'מנהלים, סגנים, רכזים פדגוגיים ומורים מובילים.', 'מנהלת מרכז החדשנות ופיתוח פדגוגי בבית רותר (מינהל החינוך חולון).', 'ביקור חצי-יומי מובנה הכולל הרצאת השראה, סדנאות Hands-on במעבדות מתקדמות, וליווי אישי של מנטור לצורך פיתוח אסטרטגיה ומיזם בית-ספרי.'),
    ('workshop', 'סדנת AI מעשית לצוות ההוראה', 'סדנת AI', 'עירוני', 'הכשרת מורים ממוקדת פדגוגיה וטכנולוגיה בשילוב AI.', 'הקניית מיומנויות לשימוש פדגוגי מעשי בבינה מלאכותית, ייעול תכנון והוראה וקידום מענה דיפרנציאלי.', 'כלל מורי בית הספר, צוותי הליבה והרכזים הפדגוגיים.', 'הפיקוח הפדגוגי העירוני ורכזי התקשוב הבית-ספריים.', 'סדרה של 3–5 מפגשים מעשיים: יצירת דפי עבודה חכמים, תמצות חומרי לימוד, חלופות הערכה מעודכנות ופינוי זמן לתקשורת אנושית עם התלמידים.'),
    ('hackathon', 'האקתון AI עירוני לפיתוח יוזמות', 'האקתון', 'עירוני', 'אירוע שיא תחרותי לפיתוח מוצרים פדגוגיים מבוססי AI.', 'עידוד יזמות פדגוגית פורצת דרך ופיתוח אבות טיפוס לכלים פדגוגיים המשלבים בינה מלאכותית.', 'צוותי מנהיגות, רכזים, מורים חדשניים ונבחרות תלמידים.', 'אגף טכנולוגיות וחדשנות חינוכית, מינהל החינוך.', 'אירוע אינטנסיבי בן יומיים הכולל האצת רעיונות, ליווי יועצים טכנולוגיים ומנטורים חינוכיים, והצגת הפרויקטים לחבר שופטים רשותי.')
  ) as x(slug, title, category, source, short, goal, audience, contact, description)
  returning 1
)
select (select count(*) from s) as sources, (select count(*) from r) as rubric, (select count(*) from b) as bank;

-- Principle 5: חינוך טכנולוגי הוליסטי וספירלי
with p as (
  insert into public.principles (
    scope, municipality_id, order_index, short_label, title, icon, color_name, accent_color,
    bg_light, text_dark, short_summary, rationale, gaps_solved, added_value,
    implementation_strategy, sacrifices_required, ecosystem_partnerships, kpis,
    teacher_deliverable, student_deliverable, first_step, is_active
  ) values (
    'municipal', '00000000-0000-4000-8000-000000000001', 5, 'חינוך הוליסטי', 'חינוך טכנולוגי הוליסטי וספירלי', 'fa-solid fa-diagram-next', 'blue', '#3b82f6',
    'bg-blue-50', 'text-blue-900', 'שילוב הטכנולוגיה בכלל מקצועות הדעת ברצף מיומנויות רב-שנתי.', 'אוריינות דיגיטלית וטכנולוגית אינה יכולה להיות מוגבלת לשיעור מחשבים מבודד. החזון מחייב תפיסה הוליסטית שבה הטכנולוגיה שזורה כחוט השני בכל מקצועות הדעת (הומניסטיקה, שפות, מדעים ואמנויות), ותפיסה ספירלית המבטיחה רצף והתפתחות של מיומנויות משכבת גיל אחת לבאה אחריה.', ARRAY['למידה מנותקת: מניעת מצב שבו תלמיד לומד כלים דיגיטליים בשיעור טכנולוגיה, אך חוזר למחברת ולשינון פסיבי בשיעור היסטוריה או ספרות.', 'חוסר רציפות: מניעת כפילויות או פערים ברמת האוריינות של תלמידים במעבר בין שכבות גיל.'], 'התלמיד מפתח תפיסה של הטכנולוגיה כשפה טבעית וכלי עבודה לפתרון בעיות אמיתיות, ולא כנושא לימוד מופשט ובודד.',
    ARRAY['ישיבות עבודה חודשיות קבועות בין רכז התקשוב לבין רכזי המקצועות השונים (רכזי שפה, מתמטיקה, מדעים) לבניית יחידות לימוד משולבות טכנולוגיה.', 'בניית מפת דרכים בית-ספרית המגדירה אילו כלים טכנולוגיים רוכש הלומד בכל שכבת גיל. המיומנות הולכת ונבנית נדבך על גבי נדבך.', 'תכנון הלימודים במקצועות הרוח, החברה והמדעים כולל שימוש קבוע ואינטגרלי בכלים דיגיטליים. שיעור היסטוריה או ספרות עושה שימוש טבעי בפלטפורמות דיגיטליות מתקדמות לצורך חקירה, פיתוח פרויקטים והצגת תוצרים.'], 'הפחתת מספר המבחנים הפרונטליים המסורתיים במקצועות השונים, לטובת משימות הערכה דיגיטליות רב-תחומיות.', 'עבודה מול משרד החינוך (הפיקוח המקצועי) לאישור חלופות בהערכה, וחיבור לתעשיות טכנולוגיות מקומיות או אקדמיה לצורך למידת עמיתים והשראה.', ARRAY['קיומה של מפת מיומנויות דיגיטליות בית-ספרית מוגדרת לכל שכבת גיל (ספירלה).', 'מספר הפרויקטים הרב-תחומיים המשולבים טכנולוגיה המבוצעים בכל מחצית.'],
    'רכזי המקצוע מחזיקים בתוכנית לימודים מעודכנת המשלבת כלי דיגיטלי ייעודי בכל רבעון פדגוגי.', 'תיק עבודות דיגיטלי (E-Portfolio) המלווה את התלמיד ומציג תוצרי למידה מבוססי טכנולוגיה ממגוון מקצועות (פודקאסט בספרות, בלוג בהיסטוריה, מודל במדעים).', 'הצגת ''מפת המיומנויות הדיגיטליות הספירלית'' לצוות בערב פתיחת השנה, והגדרת הכלי הטכנולוגי הראשון שבו כל מורי בית הספר ישתמשו עם התלמידים בשבועיים הראשונים.', true
  ) returning id
),
s as (
  insert into public.principle_sources (principle_id, title, description, url, keywords, order_index)
  select p.id, x.title, x.description, x.url, x.keywords, x.ord from p,
  (values
    ('פורטל עובדי הוראה - משרד החינוך', 'תוכנית התקשוב הלאומית המציגה את מפת האוריינות המחשבית והדיגיטלית הספירלית, כולל הגדרת יעדים ברורים מהיסודי ועד לתיכון.', 'https://info.education.gov.il', 'פדגוגיה דיגיטלית -> אוריינות דיגיטלית ספירלית', 0),
    ('אתר ה-OECD הרשמי', 'מסמך המסגרת הגלובלי Digital Literacy Framework המפרט כיצד לשזור חשיבה טכנולוגית ואלגוריתמית כחלק בלתי נפרד מכלל מקצועות החיים.', 'https://www.oecd.org', 'Education Digital Education Outlook', 1)
  ) as x(title, description, url, keywords, ord)
  returning 1
),
r as (
  insert into public.principle_rubric_levels (principle_id, level, name, description)
  select p.id, x.level, x.name, x.description from p,
  (values
    (1, 'ראשוני / ניצוצות', 'אוריינות דיגיטלית וטכנולוגית נלמדת באופן מבודד ומנותק אך ורק בשיעורי מחשבים/תקשוב ייעודיים. בשיעורים אחרים הלמידה נשארת מסורתית (מחברת וספר).'),
    (2, 'מתפתח / איים של חדשנות', 'שילוב כלים דיגיטליים מתבצע במספר מקצועות לימוד (בעיקר מדעים), אך ללא סנכרון רב-תחומי או תוכנית עבודה רציפה. אין הגדרה ברורה של רצף מיומנויות בין שכבות הגיל.'),
    (3, 'מוטמע / שגרה מוסדית', 'קיימת ''מפת מיומנויות דיגיטליות ספירלית'' בית-ספרית המגדירה יעדים לכל שכבת גיל. רכז התקשוב מקיים ישיבות עבודה חודשיות מובנות עם רכזי המקצועות (שפה, הומניסטיקה, מדעים) לשזירת הטכנולוגיה בתוכניות הלימודים השוטפות.'),
    (4, 'חלוצי / חזון עירוני מלא', 'הטכנולוגיה היא שפה טבעית וכלי עבודה קבוע בכל תחומי הדעת. הערכת התלמיד מבוססת על ''תיק עבודות דיגיטלי'' (E-Portfolio) רב-תחומי המלווה אותו בין השכבות, ומציג פיתוח חשיבה אלגוריתמית, חקר ויצירה.')
  ) as x(level, name, description)
  returning 1
),
b as (
  insert into public.activity_bank_items (
    scope, municipality_id, principle_id, slug, title, category, source,
    short, goal, audience, contact, description, is_active
  )
  select 'municipal', '00000000-0000-4000-8000-000000000001', p.id, x.slug, x.title, x.category, x.source::public.task_source,
         x.short, x.goal, x.audience, x.contact, x.description, true
  from p, (values
    ('p5-1', 'מפת מיומנויות דיגיטליות ספירלית', 'בית-ספרי', 'עירוני', 'הגדרת רצף מיומנויות לכל שכבת גיל.', 'יצירת רצף מתפתח של מיומנויות דיגיטליות מהיסודי ועד התיכון, במקום למידה מבודדת.', 'רכזי מקצוע ורכז תקשוב.', 'רכז/ת התקשוב הבית-ספרי.', 'בניית "מפת מיומנויות ספירלית" המגדירה יעדים דיגיטליים לכל שכבה ומשבצת אותם בתוכניות הלימודים.'),
    ('p5-2', 'שזירת תקשוב במקצועות הדעת', 'סדנה', 'עירוני', 'שילוב כלים דיגיטליים בהומניסטיקה ובמדעים.', 'הפיכת הטכנולוגיה לכלי עבודה טבעי בכל תחומי הדעת, לא רק בשיעורי מחשבים.', 'צוותי מקצוע.', 'רכז/ת התקשוב.', 'ישיבות עבודה חודשיות של רכז התקשוב עם רכזי המקצועות לשזירת כלים דיגיטליים בשיעורים השוטפים.'),
    ('p5-3', 'תיק עבודות דיגיטלי רב-תחומי', 'דיגיטלי', 'עירוני', 'E-Portfolio המלווה את התלמיד בין השכבות.', 'הערכה מבוססת תוצרים דיגיטליים המעידים על פיתוח חשיבה אלגוריתמית, חקר ויצירה.', 'תלמידים לאורך שכבות הגיל.', 'רכז/ת התקשוב ורכזי מקצוע.', 'הקמת תיק עבודות דיגיטלי רב-תחומי המלווה את התלמיד ומציג את התפתחותו הטכנולוגית לאורך השנים.'),
    ('p5-4', 'פורום רכז תקשוב–רכזי מקצוע', 'בית-ספרי', 'עירוני', 'סדירות תיאום לשילוב טכנולוגיה רוחבי.', 'יצירת מנגנון קבוע לסנכרון רב-תחומי של שילוב הטכנולוגיה.', 'רכזי מקצוע ותקשוב.', 'הנהלת בית הספר.', 'קביעת ישיבות עבודה קבועות לתיאום יעדים, שיתוף מערכים והבטחת רצף בין המקצועות והשכבות.'),
    ('p5-5', 'יום חשיבה חישובית עירוני', 'עירוני', 'עירוני', 'אירוע עירוני לקידום אוריינות דיגיטלית.', 'חשיפת תלמידים וצוות לחשיבה חישובית ולכלים מתקדמים במסגרת עירונית.', 'תלמידים וצוות מוביל.', 'אגף החינוך — תקשוב עירוני.', 'יום שיא עירוני ובו סדנאות, אתגרי קוד והצגת תוצרים, המקדם רצף מיומנויות בין בתי הספר.')
  ) as x(slug, title, category, source, short, goal, audience, contact, description)
  returning 1
)
select (select count(*) from s) as sources, (select count(*) from r) as rubric, (select count(*) from b) as bank;

-- Principle 6: גיוון במרחבי ובסביבות הלמידה
with p as (
  insert into public.principles (
    scope, municipality_id, order_index, short_label, title, icon, color_name, accent_color,
    bg_light, text_dark, short_summary, rationale, gaps_solved, added_value,
    implementation_strategy, sacrifices_required, ecosystem_partnerships, kpis,
    teacher_deliverable, student_deliverable, first_step, is_active
  ) values (
    'municipal', '00000000-0000-4000-8000-000000000001', 6, 'מרחבי למידה', 'גיוון במרחבי ובסביבות הלמידה', 'fa-solid fa-arrows-split-up-and-left', 'indigo', '#6366f1',
    'bg-indigo-50', 'text-indigo-900', 'הסבת שטחי בית הספר והכיתה למרחבים גמישים, היברידיים ופונקציונליים.', 'המרחב הפיזי והדיגיטלי משפיע באופן ישיר על הפדגוגיה. המבנה המסורתי של ''קופסה כיתתית'' מייצר למידה אחידה ופרונטלית. החזון דורש יצירת אקו-סיסטם היברידי (פיזי ודיגיטלי כאחד) הכולל מרחבים גמישים, דינמיים ומשתנים, התומכים בסגנונות למידה מגוונים: למידה עצמאית, עבודה שיתופית בקבוצות קטנות, והתכנסויות קהילתיות.', ARRAY['נוקשות מרחבית: שובר את המבנה המונוטוני של ישיבה ממושכת באותו חדר ובאותו סגנון לאורך כל יום הלימודים.', 'חוסר התאמה לשונות: מאפשר לתלמידים בעלי סגנונות למידה שונים (למשל, תלמידים הזקוקים לשקט מוחלט לעומת תלמידים הלומדים דרך שיח ותנועה) למצוא את מקומם בתוך המרחב.'], 'למידה עצמאית, פיתוח אחריות אישית והרחבת אפשרויות הגיוון הפדגוגי בכיתות מבוזרות.',
    ARRAY['ניהול ''מערכת שעות של מרחבים'' (ולא רק של כיתות מקור).', 'הגדרת שגרות עבודה לפתיחת וסגירת מרחבי למידה משותפים (כגון מסדרונות פעילים, ספריות מותאמות או חצרות לימודיות).', 'ביסוס סביבת למידה דיגיטלית (LMS) אחידה ופעילה המרחיבה את הלמידה מעבר לזמן הפיזי.'], 'ויתור על המושג המסורתי של ''המקום הקבוע שלי בכיתה'' למשך כל שעות היום. הפסקת ההוראה שבה המורה עומד אך ורק ליד הלוח בחזית החדר.', 'עבודה מול מחלקת בינוי וארכיטקטורה בעירוני להנדסה מחדש של מרחבים קיימים (ריהוט נייד, מחיצות, פתרונות אקוסטיים) וחיבור לרשת המחשוב.', ARRAY['שיעור הזמן השבועי שבו כיתה לומדת מחוץ למבנה הכיתה המסורתי (במרחבים גמישים או דיגיטליים).', 'שביעות רצון מורים ותלמידים מרמת האפקטיביות והמיקוד בלמידה במרחבים המשותפים.'],
    'מורה המיומן בניהול כיתה מבוזרת, ויודע לנוע במרחב בין קבוצות עבודה עצמאיות ושיתופיות.', 'תלמיד המפגין תרבות למידה עצמאית במרחב, יודע לבחור את הסביבה הנכונה עבורו למשימה ולשמור על סביבת עבודה מכבדת.', 'הגדרת ועיצוב מרחב גמיש ראשון (אפילו במסדרונות השכבה או בספרייה) עם תחילת השנה, והעברת שיעורי ההכרות הראשונים של מחנכי הכיתות במרחב זה כדי לתרגל את שגרות ההתנהגות בו.', true
  ) returning id
),
s as (
  insert into public.principle_sources (principle_id, title, description, url, keywords, order_index)
  select p.id, x.title, x.description, x.url, x.keywords, x.ord from p,
  (values
    ('משרד החינוך - אגף פיתוח סביבות למידה M21', 'קטלוגים ומאמרים המציגים את הרציונל הארכיטקטוני-פדגוגי של כיתות המאה ה-21, מרחבים גמישים (Flex Spaces) והשפעת עיצוב המרחב.', 'https://www.gov.il/he/departments/ministry_of_education', 'מרחבי למידה M21 / אגף פיתוח סביבות למידה', 0),
    ('מכון אבני ראשה', 'מאמרים העוסקים ב''הנדסה מחדש של שגרות המרחב'' ודרכים מנהלתיות לניהול מערכת שעות היברידית ודינמית המנצלת את כלל שטח בית הספר.', 'https://www.avneyrosha.org.il', 'ארגון ועיצוב מרחבי למידה משתנים', 1)
  ) as x(title, description, url, keywords, ord)
  returning 1
),
r as (
  insert into public.principle_rubric_levels (principle_id, level, name, description)
  select p.id, x.level, x.name, x.description from p,
  (values
    (1, 'ראשוני / ניצוצות', 'הלמידה מתרחשת אך ורק בתוך כיתת האם המסורתית, המאורגנת בשורות קבועות מול הלוח והמורה.'),
    (2, 'מתפתח / איים של חדשנות', 'בית הספר מחזיק ב''מרחב עתידני'' או ''כיתת חדשנות'' מעוצבת, אך ההגעה אליה היא אירוע נדיר או חגיגי. בשאר הזמן לומדים כרגיל. קיימת סביבה דיגיטלית (LMS) אך היא משמשת רק כלוח מודעות סטטי.'),
    (3, 'מוטמע / שגרה מוסדית', 'בית הספר מנהל ''מערכת שעות של מרחבים''. מסדרונות, מבואות, חצרות וספריות הוסבו למרחבים גמישים (Flex Spaces) המאפשרים למידה עצמאית או שיתופית במקביל. הסביבה הדיגיטלית הבית-ספרית פעילה, אחידה ומייצרת רצף למידה היברידי מעבר לשעות השהות הפיזיות.'),
    (4, 'חלוצי / חזון עירוני מלא', 'המרחב הפיזי והדיגיטלי מותאם לחלוטין ובאופן דינמי לשונות של הלומדים ולצרכים הפדגוגיים המשתנים. המורה מנהל כיתה מבוזרת ונע בטבעיות באקו-סיסטם היברידי עשיר ותומך למידה עצמאית עמוקה.')
  ) as x(level, name, description)
  returning 1
),
b as (
  insert into public.activity_bank_items (
    scope, municipality_id, principle_id, slug, title, category, source,
    short, goal, audience, contact, description, is_active
  )
  select 'municipal', '00000000-0000-4000-8000-000000000001', p.id, x.slug, x.title, x.category, x.source::public.task_source,
         x.short, x.goal, x.audience, x.contact, x.description, true
  from p, (values
    ('p6-1', 'הסבת מרחבים גמישים', 'בית-ספרי', 'עירוני', 'המרת מסדרונות וספרייה למרחבי למידה גמישים.', 'הרחבת הלמידה מעבר לכיתת האם והפיכת שטחי בית הספר למרחבים פונקציונליים.', 'הנהלה וצוות בית הספר.', 'אב הבית והנהלת בית הספר.', 'תכנון והסבה הדרגתית של מסדרונות, מבואות וספרייה ל-Flex Spaces המאפשרים למידה עצמאית ושיתופית.'),
    ('p6-2', 'מערכת שעות של מרחבים', 'בית-ספרי', 'עירוני', 'ניהול שיבוץ המרחבים הגמישים בבית הספר.', 'ניצול מיטבי של המרחבים החדשים והפיכת השימוש בהם לשגרה מוסדית.', 'רכז/ת מערכת שעות וצוות.', 'סגנ/ית המנהל/ת.', 'בניית "מערכת שעות של מרחבים" המאפשרת לכל כיתה לעבוד במרחב המתאים לאופי הפעילות.'),
    ('p6-3', 'סביבת LMS בית-ספרית אחידה', 'דיגיטלי', 'עירוני', 'מרחב למידה דיגיטלי אחיד ורציף.', 'יצירת רצף למידה היברידי מעבר לשעות השהות הפיזיות בבית הספר.', 'מורים ותלמידים.', 'רכז/ת התקשוב.', 'הטמעת סביבת LMS אחידה ופעילה (כמו Google Classroom) ככלי עבודה רציף ולא כלוח מודעות סטטי.'),
    ('p6-4', 'כיתת חוץ ולמידה בטבע', 'קהילה', 'עירוני', 'הסבת חצר בית הספר למרחב למידה פעיל.', 'גיוון סביבות הלמידה וחיבור הלמידה לסביבה הקרובה.', 'מחנכים ותלמידים.', 'רכז/ת קיימות / מדעים.', 'עיצוב והפעלה של כיתת חוץ בחצר בית הספר ללמידה חווייתית, מדעית וחברתית.'),
    ('p6-5', 'סיור מרחבי למידה עירוני', 'עירוני', 'עירוני', 'למידה מבתי ספר ומרחבים עירוניים מובילים.', 'שאיבת השראה ופרקטיקות לעיצוב מרחבי למידה חדשניים.', 'הנהלה וצוות מוביל.', 'אגף החינוך — בינוי ועיצוב פדגוגי.', 'סיור מקצועי במרחבי למידה עירוניים ובבתי ספר חדשניים, ולמידת מודלים ליישום בבית הספר.')
  ) as x(slug, title, category, source, short, goal, audience, contact, description)
  returning 1
)
select (select count(*) from s) as sources, (select count(*) from r) as rubric, (select count(*) from b) as bank;

-- Principle 7: תרבות מייקרינג
with p as (
  insert into public.principles (
    scope, municipality_id, order_index, short_label, title, icon, color_name, accent_color,
    bg_light, text_dark, short_summary, rationale, gaps_solved, added_value,
    implementation_strategy, sacrifices_required, ecosystem_partnerships, kpis,
    teacher_deliverable, student_deliverable, first_step, is_active
  ) values (
    'municipal', '00000000-0000-4000-8000-000000000001', 7, 'תרבות מייקרס', 'תרבות מייקרינג', 'fa-solid fa-hammer', 'orange', '#f97316',
    'bg-orange-50', 'text-orange-900', 'למידה התנסותית פיזית במרכזי חדשנות עירוניים וקידום חשיבה עיצובית.', 'למידה משמעותית מתרחשת כאשר הידע פוגש את העשייה הפיזית והיצירה. תרבות המייקרינג (Making) מעניקה לתלמידים את ההזדמנות להוציא את הלמידה מהתחום התיאורטי המופשט אל עולם המעשה המוחשי, בדרך ייחודית שמפתחת חשיבה המצאתית, יצירתיות, ותחושת מסוגלות אישית גבוהה. תפיסה זו מעודדת חשיבה עיצובית, יצירתיות, פתרון בעיות, עמידות בפני כישלונות ותחושת מסוגלות גבוהה. על מנת לממש תפיסה זו במלואה המהלך צריך להפוך לחלק אורגני מליבת העשייה החינוכית השוטפת של בית הספר.', ARRAY['למידה תיאורטית ומנותקת מחוויית העולם האמיתי: פותר את הנתק בין החומר הנלמד לבין העולם האמיתי והצורך הפיזי ביצירה.', 'קידום מיומנויות משמעותיות: חשיבה יצירתית, אוריינות חקר, פיתוח מוצר, עבודת צוות, אוריינות טכנולוגיות, חשיבה יזמית.', 'מגבלת משאבים בית-ספרית: עוקף את חוסר היכולת של בית ספר בודד להחזיק מעבדות מייקרס מתקדמות (מדפסות תלת-ממד, חותכי לייזר, כלי רובוטיקה) על ידי שימוש חכם במשאב העירוני המשותף ובתהליך משותף.'], 'פיתוח חשיבה עיצובית, יצירתיות פתרון בעיות, עמידות בפני כישלונות ותחושת מסוגלות גבוהה ביותר.',
    ARRAY['שיבוץ מובנה וקבוע של ''בלוקים'' במערכת השעות (למשל, חצי יום שבועי קבוע לשכבה מסוימת) המועתק פיזית למרכז ''אתחלא'' או ''בית רותר''.', 'למידה מבוססת תוצרים (PBL): שילוב פרויקטים שנתיים או סמסטריאליים בתוכנית הלימודים, שבהם התלמידים מתכננים ומייצרים מוצרים אמיתיים הנותנים מענה לאתגרים קהילתיים או מדעיים.', 'קיום הדרכה שוטפת (ממומנת ממרכז אתחלא ובית רותר) למוביל בית ספרי מייקרי.'], 'ויתור על שעות הוראה פרונטליות בכיתת האם לטובת למידה מבוססת פרויקטים (PBL) במרחבים העירוניים. ויתור על חלוקת הזמן הנוקשה של שיעורים בני 45 דקות.', 'סנכרון תפעולי ופדגוגי הדוק מול מנהלי המרכזים העירוניים, תיאום מערך הסעות עירוני קבוע, ושותפות עם גורמי קהילה לזיהוי אתגרים מקומיים שהתלמידים יכולים לייצר עבורם פתרון.', ARRAY['אחוז שכבות הגיל המקיימות רצף עבודה קבוע במרחבים העירוניים במהלך השנה.', 'מספר התוצרים הפיזיים/דיגיטליים העומדים בקריטריונים של מוצר עובד בסוף תהליך.'],
    'מורה שמיומן בהנחיית למידה מבוססת פרויקטים ובשיתוף פעולה עם מנטורים מקצועיים במרכזים העירוניים.', 'תוצר פיזי או דיגיטלי עובד (אב-טיפוס, מוצר רובוטי, דגם מעוצב) שנותן מענה לבעיה מוגדרת המוגש בתערוכה עירונית/קהילתית.', 'קיום ישיבת הנהלה משותפת עם נציגי ''אתחלא'' ו''בית רותר'' בשבועיים הראשונים של השנה, לחתימה על גאנט העבודה המשותף ושיבוץ השכבות במערכת.', true
  ) returning id
),
s as (
  insert into public.principle_sources (principle_id, title, description, url, keywords, order_index)
  select p.id, x.title, x.description, x.url, x.keywords, x.ord from p,
  (values
    ('הקרן לעידוד יוזמות חינוכיות', 'מאגר עצום של יוזמות שטח מבוססות תרבות המייקינג (Making) ולמידה התנסותית, המציג מודלים של עבודה מחוץ לכותלי בית הספר.', 'https://www.yozo.org.il', 'למידת מייקרים / PBL באקו סיסטם', 0),
    ('מכון ברנקו וייס', 'תיאוריות ומדריכים על ''למידה מבוססת מקום'' (Place-Based Education) ופדגוגיה של פרויקטים המשלבת ידיים עובדות וחשיבה עיצובית.', 'https://brancoweiss.org.il', 'משאבים ומאמרים -> למידה מבוססת פרויקטים', 1)
  ) as x(title, description, url, keywords, ord)
  returning 1
),
r as (
  insert into public.principle_rubric_levels (principle_id, level, name, description)
  select p.id, x.level, x.name, x.description from p,
  (values
    (1, 'ראשוני / ניצוצות', 'תלמידי בית הספר יוצאים לסיור או פעילות העשרה חד-פעמית במרכזי החדשנות העירוניים (''אתחלא'' / ''בית רותר''). הפעילות מהנה אך מנותקת לחלוטין מתוכנית הלימודים ומליבת העשייה הבית-ספרית.'),
    (2, 'מתפתח / איים של חדשנות', 'מספר מצומצם של כיתות או מורים מובילים פרויקט למידה מבוסס פרויקטים (PBL) בשיתוף המרכזים העירוניים. האתגר הלוגיסטי (הסעות, התאמת מערכת) עדיין מנוהל באופן נקודתי ומקשה על הרחבת הפעילות.'),
    (3, 'מוטמע / שגרה מוסדית', 'שיבוץ מובנה וקבוע של ''בלוקים'' ארוכים במערכת השעות עבור שכבות גיל מוגדרות, שבהם הלמידה מועתקת פיזית ובאופן שבועי/דו-שבועי ל''אתחלא'' או ''בית רותר''. נעשה ויתור מודע על שעות פרונטליות בכיתה לטובת עבודה על פרויקטים מובנים במרחבים אלו.'),
    (4, 'חלוצי / חזון עירוני מלא', 'בית הספר פועל באקו-סיסטם קהילתי-עירוני מלא. תלמידים מתכננים ומייצרים במרכזים העירוניים תוצרים פיזיים וטכנולוגיים עובדים הנותנים מענה לאתגרים ובעיות אמיתיות בעיר, והתוצרים מוצגים בתערוכות רשמיות וזוכים להערכה חלופית רחבה.')
  ) as x(level, name, description)
  returning 1
),
b as (
  insert into public.activity_bank_items (
    scope, municipality_id, principle_id, slug, title, category, source,
    short, goal, audience, contact, description, is_active
  )
  select 'municipal', '00000000-0000-4000-8000-000000000001', p.id, x.slug, x.title, x.category, x.source::public.task_source,
         x.short, x.goal, x.audience, x.contact, x.description, true
  from p, (values
    ('p7-1', 'בלוק מייקרינג שבועי', 'בית-ספרי', 'עירוני', 'שיבוע קבוע של למידה התנסותית ויצירה.', 'קיבוע למידה מבוססת עשייה ויצירת מוצרים פיזיים כחלק משגרת בית הספר.', 'שכבת גיל נבחרת.', 'רכז/ת חדשנות / מדעים.', 'שיבוץ "בלוק פתוח" שבועי במערכת ללמידה התנסותית, חשיבה עיצובית ויצירת תוצרים מוחשיים.'),
    ('p7-2', 'למידה במרכזי חדשנות עירוניים', 'עירוני', 'עירוני', 'למידה ב"אתחלא" / בית רותר באופן קבוע.', 'מינוף משאבי הרשות ללמידה מעשית במרחבי מייקרינג מקצועיים.', 'כיתות ושכבות נבחרות.', 'מינהל החינוך — מרכזי החדשנות העירוניים.', 'העתקת חלק מהלמידה באופן שבועי/דו-שבועי למרכזי החדשנות העירוניים לעבודה על פרויקטים מובנים.'),
    ('p7-3', 'תערוכת תוצרים בית-ספרית', 'קהילה', 'עירוני', 'יריד להצגת תוצרי המייקרינג של התלמידים.', 'הערכה חלופית והנכחת תרבות העשייה בפני קהילת בית הספר.', 'תלמידים, מורים והורים.', 'רכז/ת חברתי וצוות מוביל.', 'אירוע שיא שבו התלמידים מציגים מוצרים פיזיים וטכנולוגיים שפיתחו, עם הערכה חלופית רחבה.'),
    ('p7-4', 'סדנת חשיבה עיצובית (Design Thinking)', 'סדנה', 'עירוני', 'הקניית מתודולוגיית פיתוח מוצר לצוות.', 'הטמעת שפת חשיבה עיצובית ככלי לפיתוח פתרונות לבעיות אמיתיות.', 'מורים מובילים ותלמידים.', 'מנחה חיצוני / מרכז החדשנות.', 'סדנה מעשית בתהליך Design Thinking: הזדהות עם בעיה, רעיונאות, אב טיפוס ובדיקה.'),
    ('p7-5', 'שותפות עם תעשייה ואקדמיה מקומית', 'עירוני', 'עירוני', 'חיבור התלמידים לאתגרים אמיתיים בעיר.', 'פיתוח מוצרים הנותנים מענה לאתגרים אמיתיים בקהילה ובעיר.', 'נבחרות תלמידים.', 'אגף החינוך — שותפויות אקו-סיסטם.', 'יצירת שותפות עם גוף תעשייה/אקדמיה מקומי לליווי פרויקטים ופיתוח תוצרים יישומיים.')
  ) as x(slug, title, category, source, short, goal, audience, contact, description)
  returning 1
)
select (select count(*) from s) as sources, (select count(*) from r) as rubric, (select count(*) from b) as bank;

